import java.io.*;
import java.util.*;
import java.text.*;
import java.lang.*;
import java.math.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter out = new PrintWriter(System.out);
    static final long MOD = 1000000007;
    static final long MOD1 = 998244353;

    public static void main(String[] args) throws Exception {
        long n = getNextLong();
        long m = getNextLong();
        long l = getNextLong();
        long r = getNextLong();

        long segmentLength = r - l + 1;
        long halfSegment = segmentLength / 2;
        long otherHalfSegment = segmentLength - halfSegment;
        long totalCells = n * m;

        long answer;
        if (totalCells % 2 == 1) {
            answer = segmentLength % MOD;
        } else {
            long sumOfParts = (powerMod(halfSegment + otherHalfSegment, totalCells, MOD) + powerMod(Math.abs(halfSegment - otherHalfSegment), totalCells, MOD)) % MOD;
            answer = (sumOfParts * inverseMod(2, MOD)) % MOD;
        }
        out.println(answer);
        out.flush();
        out.close();
    }

    static long getNextLong() throws IOException {
        String[] parts = br.readLine().split(" ");
        return Long.parseLong(parts[0]);
    }

    static long powerMod(long base, long exp, long mod) {
        long result = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * b) % mod;
            b = (b * b) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long inverseMod(long a, long m) {
        return powerMod(a, m - 2, m);
    }
}
